class DiagnosisProbe(view, device):
    run_full_diagnosis(train_loader):
        remember view.model.training
        set model to evaluation mode
        initialize measurement accumulators
        with gradients disabled:
            for _, sequence, positive, negative in train_loader:
                features = view.log2feats(sequence)
                identify valid history positions and targets
                compute supported probes using features,
                    view.item_emb and view.predict_score
                accumulate measurements and sample counts
        restore previous model mode
        return {metrics: aggregated measurements,
                metric_definitions: definitions, masks, units and limitations}

def diagnosis_interpreter_prompt(raw_diagnosis):
    return prompt containing measured metrics and their definitions,
        requesting evidence-grounded interpretation and HSTU-compatible
        single-model improvements, with unavailable evidence stated explicitly
